css:
.card-container {
  display: flex;
  justify-content: center;
  align-items: center;
}

.credit-card {
  background: linear-gradient(145deg, #7dbbcc, #aa1100);
  border-radius: 16px;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.2);
  color: white;
  padding: 0;
  position: relative;
}

.inner {
  width: 320px;
  height: 150px;
  background: inherit;
  border-radius: 16px;
  box-shadow: inherit;
  color: white;
  padding: 20px;
  position: relative;
}

.magnetic-strip {
  width: 100%;
  height: 30px;
  margin-top: 20px;
  background: linear-gradient(90deg, #000000, #434343 20%, #000000);
  border-radius: 4px;
}

.card-number {
  margin-top: -10px;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 2px;
}

.card-details {
  display: flex;
  justify-content: space-between;
  margin-top: 14px;
}

.card-details div {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.card-details label,
.number-label {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.7);
  margin-bottom: 5px;
}

.card-name,
.card-date {
  color: white;
  font-size: 12px;
  font-weight: 900;
}

.number-label {
  font-size: 10px;
}
